<script setup lang="ts">
import axios from 'axios';
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import {api,errorMessage} from '../api';
import {amount} from '../catalog';
import {units,type SavedOrder} from '../sales';
import {readPending,savePending,clearPending} from '../lib/pendingRequests';
import AppDialog from './AppDialog.vue';
import {downloadPrivatePdf} from '../lib/downloadPdf';
import RefundReversal from './RefundReversal.vue';
import {refundReversalText as ft} from '../locales/es/refundReversal';
import ReturnAdjustmentReversal from './ReturnAdjustmentReversal.vue';
import {adjustmentReversalText as at} from '../locales/es/adjustmentReversal';
type Proposal={version:number;currency:string;invoice_number:string;lines:{name:string;quantity:string;credit_amount:string}[];shipping_credit:string;shipping_available:string;merchandise_credit:string;amount:string;net_after:string;credit_released:string;debt_reduction:string;review_hash:string};
type Source={payment_id:number;released:string;refunded:string;available_credit:string;max_refund:string;method:string};
type State={state:'received'|'adjusted';version?:number;currency?:string;invoice_number?:string;proposal?:Proposal;adjustment?:{id:number;amount:string;credit_released:string;reason:string;actor_name:string};balance?:{net_total:string;pending_total:string;credit_available:string;refunded_total:string};refund_sources?:Source[];refunds?:{id:number;amount:string;method:string;external_reference:string|null;actor_name:string;reversal?:{id:number;reason:string;actor_name:string;created_at:string}|null}[];history?:{id:number;amount:string;reason:string;actor_name:string;created_at:string;reversal:{id:number;reason:string;actor_name:string;created_at:string}|null}[]};
type Pending={kind:'adjust'|'refund';payload:Record<string,unknown>&{request_key:string}};
const props=defineProps<{root:string;actorId:number;orderId:number;receiptId:number;canAdjust:boolean;canRefund:boolean;canDownload?:boolean;canReverseRefund?:boolean;canReverseAdjustment?:boolean;returnFocus:HTMLElement|null}>();
const emit=defineEmits<{changed:[SavedOrder];closed:[]}>();const endpoint=`${props.root}/sales/orders/${props.orderId}/returns/${props.receiptId}`;const journal=`bshop:return-financial:${props.actorId}:${props.root}:${props.orderId}:${props.receiptId}`;
const open=ref(true);const busy=ref(false);const error=ref('');const notice=ref('');const state=ref<State|null>(null);const shipping=ref('0');const reason=ref('');const selected=ref<Source|null>(null);const refundAmount=ref('');const method=ref('cash');const reference=ref('');const pending=ref<Pending|null>(null);let alive=true;
const reversingRefund=ref<number|null>(null);const refundOpener=ref<HTMLElement|null>(null);const refundJournal=`bshop:refund-reversal:${props.actorId}:${props.root}:${props.orderId}`;
const reversingAdjustment=ref<number|null>(null);const adjustmentOpener=ref<HTMLElement|null>(null);const adjustmentJournal=`bshop:adjustment-reversal:${props.actorId}:${props.root}:${props.orderId}`;
async function undoAdjustment(id:number,event:Event){if(busy.value||pending.value||!props.canReverseAdjustment)return;adjustmentOpener.value=event.currentTarget as HTMLElement;open.value=false;await nextTick();reversingAdjustment.value=id;}
async function adjustmentUndone(order:SavedOrder){emit('changed',order);notice.value=at.success;selected.value=null;reason.value='';shipping.value='0';try{await load();}catch(e){error.value=explain(e);}}
async function adjustmentUndoClosed(){reversingAdjustment.value=null;await nextTick();open.value=true;try{await load();}catch(e){error.value=explain(e);}}
async function correctRefund(id:number,event:Event){if(busy.value||pending.value||!props.canReverseRefund)return;refundOpener.value=event.currentTarget as HTMLElement;open.value=false;await nextTick();reversingRefund.value=id;}
async function refundCorrected(order:SavedOrder){emit('changed',order);notice.value=ft.success;try{await load();}catch(e){error.value=explain(e);}}
async function refundCorrectionClosed(){reversingRefund.value=null;await nextTick();open.value=true;try{await load();}catch(e){error.value=explain(e);}}
const currency=computed(()=>state.value?.proposal?.currency||state.value?.currency||'USD');
const adjustReady=computed(()=>!!state.value?.proposal&&reason.value.trim().length>=5&&units(shipping.value)!==null&&units(shipping.value)===units(state.value.proposal.shipping_credit));
const refundReady=computed(()=>{const n=units(refundAmount.value);const max=units(selected.value?.max_refund||'0');return !!selected.value&&n!==null&&max!==null&&n>0n&&n<=max&&reason.value.trim().length>=5&&(method.value==='cash'||!!reference.value.trim());});
const explain=(e:unknown)=>axios.isAxiosError(e)&&e.response&&[409,422].includes(e.response.status)&&typeof e.response.data?.message==='string'&&!e.response.data?.errors?e.response.data.message:errorMessage(e);
async function load(){const result=(await api.get(endpoint+'/financial',{params:{shipping_credit:shipping.value}})).data.data as State;if(alive){state.value=result;if(selected.value)selected.value=result.refund_sources?.find(s=>s.payment_id===selected.value?.payment_id)||null;}}
async function refresh(){if(busy.value||pending.value)return;busy.value=true;error.value='';try{await load();}catch(e){if(alive)error.value=explain(e);}finally{if(alive)busy.value=false;}}
function choose(source:Source){selected.value=source;refundAmount.value=source.max_refund;method.value=['cash','card','bank_transfer'].includes(source.method)?source.method:'cash';reference.value='';reason.value='';notice.value='';}
async function finish(order:SavedOrder,recovered=false){if(!alive)return;pending.value=null;selected.value=null;reason.value='';error.value='';notice.value=recovered?'Operación financiera recuperada sin repetir movimientos.':'Operación financiera registrada.';try{clearPending(journal);}catch{}emit('changed',order);await load();}
async function send(){
    if(busy.value)return;error.value='';
    if(!pending.value){let operation:Pending;if(state.value?.state==='received'){if(!props.canAdjust||!adjustReady.value||!state.value.proposal)return;operation={kind:'adjust',payload:{request_key:crypto.randomUUID(),version:state.value.proposal.version,review_hash:state.value.proposal.review_hash,shipping_credit:shipping.value,reason:reason.value}};}else{if(!props.canRefund||!refundReady.value||!selected.value)return;operation={kind:'refund',payload:{request_key:crypto.randomUUID(),version:state.value?.version,payment_id:selected.value.payment_id,amount:refundAmount.value,method:method.value,external_reference:reference.value||null,reason:reason.value}};}try{savePending(journal,operation as unknown as Record<string,unknown>);pending.value=operation;}catch{error.value='No se pudo guardar recuperación. No se enviaron cambios.';return;}}
    if(pending.value.kind==='adjust'&&!props.canAdjust||pending.value.kind==='refund'&&!props.canRefund)return;
    busy.value=true;try{await finish((await api.post(`${endpoint}/${pending.value.kind}`,pending.value.payload)).data.data.order);}catch(e){if(alive){error.value=explain(e);if(axios.isAxiosError(e)&&e.response&&[409,422].includes(e.response.status)){pending.value=null;try{clearPending(journal);}catch{}}}}finally{if(alive)busy.value=false;}
}
async function recover(){if(!pending.value||busy.value)return;busy.value=true;error.value='';try{await finish((await api.get(`${endpoint}/financial/requests/${pending.value.payload.request_key}`,{params:{operation:pending.value.kind}})).data.data.order,true);}catch(e){if(alive)error.value=axios.isAxiosError(e)&&e.response?.status===404?'La operación no está confirmada. Reintenta el mismo UUID.':explain(e);}finally{if(alive)busy.value=false;}}
function close(){if(!busy.value){open.value=false;emit('closed');}}
async function download(id=state.value?.adjustment?.id){if(busy.value||pending.value||!props.canDownload||!id)return;busy.value=true;error.value='';try{const result=(await api.post(`${props.root}/sales/orders/${props.orderId}/documents/adjustment/${id}`)).data.data;await downloadPrivatePdf(result.url,result.filename);}catch(e){if(alive)error.value=explain(e);}finally{if(alive)busy.value=false;}}
onMounted(async()=>{const undoing=readPending(adjustmentJournal);if(props.canReverseAdjustment&&undoing?.receiptId===props.receiptId&&Number.isInteger(undoing.adjustmentId)){open.value=false;await nextTick();reversingAdjustment.value=Number(undoing.adjustmentId);return;}const correcting=readPending(refundJournal);if(props.canReverseRefund&&correcting?.receiptId===props.receiptId&&Number.isInteger(correcting.refundId)){open.value=false;await nextTick();reversingRefund.value=Number(correcting.refundId);return;}const saved=readPending(journal) as unknown as Pending|null;if(saved&&['adjust','refund'].includes(saved.kind)&&typeof saved.payload?.request_key==='string'){pending.value=saved;reason.value=String(saved.payload.reason||'');shipping.value=String(saved.payload.shipping_credit||'0');}busy.value=true;try{await load();}catch(e){error.value=explain(e);}finally{busy.value=false;}if(pending.value)await recover();});onUnmounted(()=>{alive=false;});
</script>
<template><AppDialog :open="open" title="Conciliación de devolución" :busy="busy" :return-focus="returnFocus" @close="close">
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="notice" class="notice success" role="status">{{ notice }}</p><p v-if="busy" role="status">Consultando conciliación…</p><p v-if="pending" class="notice">Hay una operación sin respuesta confirmada; conserva UUID e importes.</p>
    <template v-if="state?.state==='received'&&state.proposal"><p><strong>{{ state.proposal.invoice_number }}</strong> · Recepción #{{ receiptId }}</p><p>Propuesta basada en precios, descuentos e impuestos originales. El envío se acredita sólo por el importe indicado.</p><article v-for="(line,index) in state.proposal.lines" :key="index"><strong>{{ line.name }}</strong><p>{{ line.quantity }} · Crédito {{ amount(line.credit_amount,currency) }}</p></article>
        <label>Envío a acreditar<input v-model="shipping" inputmode="decimal" maxlength="20" :disabled="busy||!!pending||!canAdjust"></label><p>Envío original aún acreditable: {{ amount(state.proposal.shipping_available,currency) }}</p><button type="button" class="button secondary" :disabled="busy||!!pending" @click="refresh">Actualizar propuesta económica</button>
        <dl><dt>Mercancía neta con impuestos</dt><dd>{{ amount(state.proposal.merchandise_credit,currency) }}</dd><dt>Ajuste total</dt><dd>{{ amount(state.proposal.amount,currency) }}</dd><dt>Nuevo total neto del pedido</dt><dd>{{ amount(state.proposal.net_after,currency) }}</dd><dt>Reducción de deuda</dt><dd>{{ amount(state.proposal.debt_reduction,currency) }}</dd><dt>Crédito liberado</dt><dd>{{ amount(state.proposal.credit_released,currency) }}</dd></dl>
        <label v-if="canAdjust">Motivo del ajuste<textarea v-model="reason" minlength="5" maxlength="255" rows="3" :disabled="busy||!!pending"></textarea></label>
    </template>
    <template v-if="state?.state==='adjusted'&&state.adjustment&&state.balance"><p><strong>Ajuste #{{ state.adjustment.id }}</strong> · {{ state.adjustment.actor_name }}</p><p>{{ state.adjustment.reason }}</p><dl><dt>Crédito aprobado</dt><dd>{{ amount(state.adjustment.amount,currency) }}</dd><dt>Total neto del pedido</dt><dd>{{ amount(state.balance.net_total,currency) }}</dd><dt>Pendiente por cobrar</dt><dd>{{ amount(state.balance.pending_total,currency) }}</dd><dt>Saldo a favor disponible</dt><dd>{{ amount(state.balance.credit_available,currency) }}</dd><dt>Reembolsado registrado</dt><dd>{{ amount(state.balance.refunded_total,currency) }}</dd></dl>
        <button v-if="canReverseAdjustment" type="button" class="button secondary" :disabled="busy||!!pending" :aria-label="at.actionAria(state.adjustment.id)" @click="undoAdjustment(state.adjustment.id,$event)">{{ at.action }}</button>
        <section aria-label="Crédito por pago original"><h3>Crédito liberado por pago</h3><article v-for="source in state.refund_sources" :key="source.payment_id"><p>Pago #{{ source.payment_id }} · Máximo reembolsable ahora {{ amount(source.max_refund,currency) }}</p><button v-if="canRefund" type="button" class="button secondary" :disabled="busy||!!pending||units(source.max_refund)===0n" :aria-label="`Preparar reembolso del pago #${source.payment_id}`" @click="choose(source)">Preparar registro de reembolso</button></article><p v-if="!state.refund_sources?.length">El ajuste redujo deuda; no hay asignaciones liberadas para reembolsar.</p></section>
        <fieldset v-if="selected&&canRefund" class="form-fields" :disabled="busy||!!pending"><p>Registro de dinero ya devuelto al cliente. No ejecuta una transferencia ni un reembolso de tarjeta.</p><label>Importe reembolsado<input v-model="refundAmount" inputmode="decimal" maxlength="20"></label><label>Método del reembolso<select v-model="method"><option value="cash">Efectivo</option><option value="bank_transfer">Transferencia</option><option value="card">Tarjeta</option></select></label><label>Referencia del reembolso<input v-model="reference" maxlength="160"></label><label>Motivo del reembolso<textarea v-model="reason" minlength="5" maxlength="255" rows="3"></textarea></label></fieldset>
        <section aria-label="Reembolsos registrados"><h3>Reembolsos registrados</h3><article v-for="refund in state.refunds" :key="refund.id"><p>#{{ refund.id }} · {{ amount(String(refund.amount),currency) }} · {{ refund.method }} · {{ refund.external_reference||'Sin referencia externa' }} · {{ refund.actor_name }}</p><p v-if="refund.reversal" class="notice">{{ ft.corrected }} · {{ refund.reversal.reason }} · {{ refund.reversal.actor_name }} · {{ refund.reversal.created_at }}</p><button v-if="canReverseRefund&&!refund.reversal" type="button" class="button secondary" :disabled="busy||!!pending" :aria-label="ft.actionAria(refund.id)" @click="correctRefund(refund.id,$event)">{{ ft.action }}</button></article></section><button type="button" class="button secondary" :disabled="busy||!!pending" @click="refresh">Actualizar conciliación</button>
    </template>
    <button v-if="pending" type="button" class="button secondary" :disabled="busy" @click="recover">Comprobar operación financiera</button>
    <section v-if="state?.history?.length" :aria-label="at.history"><h3>{{ at.history }}</h3><article v-for="entry in state.history" :key="entry.id"><strong>{{ at.reference(entry.id) }} · {{ amount(entry.amount,currency) }} · {{ entry.reversal?at.reversed:at.current }}</strong><p>{{ entry.reason }} · {{ entry.actor_name }} · {{ entry.created_at }}</p><p v-if="entry.reversal" class="notice">{{ entry.reversal.reason }} · {{ entry.reversal.actor_name }} · {{ entry.reversal.created_at }}</p><button v-if="canDownload" type="button" class="button secondary" :disabled="busy||!!pending" :aria-label="at.downloadAria(entry.id)" @click="download(entry.id)">{{ at.download }}</button></article></section>
    <p v-if="pending?.kind==='refund'" class="notice">Reembolso pendiente de respuesta: {{ amount(String(pending.payload.amount||'0'),currency) }} · {{ pending.payload.method }} · {{ pending.payload.external_reference||'Sin referencia externa' }}</p>
    <template #footer><button type="button" class="button secondary" :disabled="busy" @click="close">Volver a recepción</button><button v-if="state?.adjustment&&canDownload" type="button" class="button secondary" :disabled="busy||!!pending" @click="download()">Descargar comprobante de ajuste</button><button v-if="pending" type="button" class="button primary" :disabled="busy||(pending.kind==='adjust'?!canAdjust:!canRefund)" @click="send">Reintentar operación financiera</button><button v-else-if="state?.state==='received'&&canAdjust" type="button" class="button primary" :disabled="busy||!adjustReady" @click="send">Confirmar ajuste económico</button><button v-else-if="selected&&canRefund" type="button" class="button primary" :disabled="busy||!refundReady" @click="send">Registrar reembolso realizado</button></template>
</AppDialog><RefundReversal v-if="reversingRefund" :root="root" :actor-id="actorId" :order-id="orderId" :receipt-id="receiptId" :refund-id="reversingRefund" :return-focus="refundOpener" @changed="refundCorrected" @closed="refundCorrectionClosed"/><ReturnAdjustmentReversal v-if="reversingAdjustment" :root="root" :actor-id="actorId" :order-id="orderId" :receipt-id="receiptId" :adjustment-id="reversingAdjustment" :return-focus="adjustmentOpener" @changed="adjustmentUndone" @closed="adjustmentUndoClosed"/></template>
<style scoped>dl{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;margin:20px 0}dd{margin:0;white-space:nowrap;font-weight:650}article{padding:14px 0;border-bottom:1px solid #e4ddec}p,strong,dt{overflow-wrap:anywhere}h3{margin:20px 0 12px}section,fieldset{margin-top:20px}</style>
